css:
.sr {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;display:flex;gap:10px;border-radius:var(--radius-md);padding:6px 8px;height:52px;align-items:flex-start;transition:background-color 100ms;cursor:pointer;user-select:none;width:100%}
.sr:hover, .sr[data-state="hover"] {background:var(--color-secondary)}
.sr[data-state="active"] {background:var(--color-secondary)}
.sr .col {display:flex;min-width:0;flex:1;flex-direction:column;gap:4px}
.sr .l1 {display:flex;height:20px;min-width:0;align-items:center;gap:8px}
.sr .tt {min-width:0;flex:1;overflow:hidden;white-space:nowrap;font-size:var(--text-base);line-height:20px;font-weight:var(--font-weight-normal);color:color-mix(in srgb,var(--color-foreground) 90%,transparent);-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 24px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 24px),transparent);letter-spacing:var(--tracking-tight)}
.sr:hover .tt, .sr[data-state="hover"] .tt, .sr[data-state="active"] .tt {color:var(--color-foreground)}
.sr .tm {flex-shrink:0;font-size:var(--text-xs);color:var(--color-muted-foreground-1);font-variant-numeric:tabular-nums;letter-spacing:var(--tracking-normal)}
.sr .l2 {display:flex;height:16px;min-width:0;align-items:center;gap:6px;font-size:var(--text-xs);color:var(--color-muted-foreground-2);letter-spacing:var(--tracking-normal)}
.sr .pc {display:flex;flex-shrink:0;opacity:.8}
.sr .pn {min-width:0;flex:1;overflow:hidden;white-space:nowrap}
.sr .mc {display:flex;max-width:60%;min-width:0;flex-shrink:0;align-items:center;gap:6px;opacity:.8}
.sr .mc svg {width:12px;height:12px;flex-shrink:0}
